css:
.resiliencesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1c2733;
    background: linear-gradient(160deg, #eef1f5 0%, #e2e7ee 100%);
    border-radius: 18px;
}

.resiliencesim-container * {
    box-sizing: border-box;
}

.resiliencesim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #16222e 0%, #233747 55%, #2f5a6e 100%);
    color: #f2f6f9;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(22, 34, 46, 0.32);
    border-top: 4px solid #e6a817;
}

.resiliencesim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.resiliencesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #ffd98a;
    background: rgba(230, 168, 23, 0.16);
    padding: 5px 14px;
    border-radius: 999px;
}

.resiliencesim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #dbe5ec;
}

.resiliencesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2a4150;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.resiliencesim-period-counter #currentDay,
.resiliencesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #16222e;
}

.resiliencesim-round-name {
    background: #d4dee6;
    color: #16222e;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.resiliencesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a4310;
    background: #fbe7d4;
    padding: 4px 12px;
    border-radius: 999px;
}

.resiliencesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.resiliencesim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d3dde6;
    box-shadow: 0 4px 14px rgba(22, 34, 46, 0.06);
    border-top: 4px solid #2f5a6e;
}

.resiliencesim-card-resilience { border-top-color: #1d7a5f; }
.resiliencesim-card-existential { border-top-color: #c0392b; }
.resiliencesim-card-adaptive { border-top-color: #2f6fb0; }
.resiliencesim-card-budget { border-top-color: #e6a817; }

.resiliencesim-label {
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #5d7280;
}

.resiliencesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #16222e;
}

.resiliencesim-card-resilience .resiliencesim-value { color: #1d7a5f; }
.resiliencesim-card-existential .resiliencesim-value { color: #c0392b; }
.resiliencesim-card-adaptive .resiliencesim-value { color: #2f6fb0; }
.resiliencesim-card-budget .resiliencesim-value { color: #b9820c; }

.resiliencesim-sublabel {
    font-size: 0.76rem;
    color: #6f8492;
    line-height: 1.35;
}

.resiliencesim-resilience-fail .resiliencesim-value { color: #c0392b; }
.resiliencesim-resilience-target .resiliencesim-value { color: #1d7a5f; }

.resiliencesim-existential-covered { border-top-color: #1d7a5f; }
.resiliencesim-existential-covered .resiliencesim-value { color: #1d7a5f; }

.resiliencesim-budget-over { border-top-color: #c0392b; }
.resiliencesim-budget-over .resiliencesim-value { color: #c0392b; }

.resiliencesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #16222e;
    color: #eaf1f5;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.resiliencesim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #ffd98a;
}

.resiliencesim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #2f5a6e;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(22, 34, 46, 0.05);
}

.resiliencesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.resiliencesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #16222e;
    margin-bottom: 6px;
}

.resiliencesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2c3e4a;
}

.resiliencesim-briefing-text strong { color: #1d7a5f; }
.resiliencesim-briefing-text em { color: #9a4310; font-style: italic; }

.resiliencesim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d3dde6;
    box-shadow: 0 4px 14px rgba(22, 34, 46, 0.06);
}

.resiliencesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #16222e;
    border-bottom: 2px solid #e2e7ee;
    padding-bottom: 8px;
}

.resiliencesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #20323f;
    margin: 14px 0 6px;
}

.resiliencesim-container select,
.resiliencesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #b6c6d1;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f6f9fb;
    color: #1c2733;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.resiliencesim-container select:focus,
.resiliencesim-container input[type="number"]:focus {
    outline: none;
    border-color: #2f5a6e;
    box-shadow: 0 0 0 3px rgba(47, 90, 110, 0.16);
}

.resiliencesim-container select option {
    background-color: #ffffff;
    color: #1c2733;
}

.resiliencesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2f5a6e;
}

.resiliencesim-range-readout,
.resiliencesim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2f5a6e;
    margin-top: 4px;
}

.resiliencesim-range-readout span:last-child,
.resiliencesim-alloc-readout span:nth-child(2) {
    color: #1d7a5f;
    font-weight: 800;
}

.resiliencesim-hint {
    font-size: 0.8rem;
    color: #6f8492;
    margin-top: 4px;
    line-height: 1.4;
}

.resiliencesim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.resiliencesim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f1f5f8;
    border: 1px solid #dae3ea;
    border-radius: 9px;
    padding: 8px 12px;
}

.resiliencesim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #20323f;
}

.resiliencesim-alloc-row input[type="number"] {
    width: 96px;
    flex: 0 0 96px;
}

.resiliencesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.resiliencesim-container .btn-primary {
    background: linear-gradient(135deg, #1d7a5f 0%, #2f5a6e 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(29, 122, 95, 0.28);
}

.resiliencesim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.resiliencesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #b6c6d1;
    color: #5d7280;
}

.resiliencesim-coach {
    background: #16222e;
    color: #eaf1f5;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(22, 34, 46, 0.24);
    border-left: 5px solid #e6a817;
}

.resiliencesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #8fbac8;
    margin-bottom: 8px;
}

.resiliencesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.resiliencesim-coach-body strong { color: #ffd98a; }
.resiliencesim-coach-body em { color: #ffc1ad; font-style: italic; }

.resiliencesim-history,
.resiliencesim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d3dde6;
    box-shadow: 0 4px 14px rgba(22, 34, 46, 0.06);
}

.resiliencesim-history h3,
.resiliencesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #16222e;
}

.resiliencesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #20323f;
}

.resiliencesim-container table#usfHistoryTable th {
    background: #e9eff4;
    color: #16222e;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #cfdbe4;
}

.resiliencesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef3f6;
}

.resiliencesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7fafc;
}

.resiliencesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .resiliencesim-container {
        padding: 14px;
    }
    .resiliencesim-header h1 {
        font-size: 1.7rem;
    }
    .resiliencesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .resiliencesim-value {
        font-size: 2rem;
    }
    .resiliencesim-clock {
        margin-left: 0;
    }
    .resiliencesim-period-counter {
        font-size: 0.88rem;
    }
    .resiliencesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .resiliencesim-alloc-row {
        flex-wrap: wrap;
    }
    .resiliencesim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .resiliencesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion message (formatCompletionMessage) — self-contained, readable on the white modal */
.resiliencesim-completion { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #17283c; }
.resiliencesim-cm-head { display: flex; align-items: center; gap: 18px; flex-wrap: wrap; padding-bottom: 14px; border-bottom: 1px solid rgba(23,40,60,0.15); margin-bottom: 16px; }
.resiliencesim-cm-score { font-size: 46px; font-weight: 800; line-height: 1; color: #1f6a7a; }
.resiliencesim-cm-score-max { font-size: 18px; font-weight: 600; color: #45607f; margin-left: 2px; }
.resiliencesim-cm-grade { font-size: 18px; font-weight: 700; color: #17283c; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.resiliencesim-cm-badge { display: inline-block; font-size: 12px; font-weight: 700; letter-spacing: .02em; padding: 3px 10px; border-radius: 999px; }
.resiliencesim-cm-yes { background: rgba(31,106,122,0.16); color: #185663; }
.resiliencesim-cm-no { background: rgba(176,51,37,0.12); color: #b03325; }
.resiliencesim-cm-warn { background: rgba(180,110,20,0.16); color: #8a5410; }
.resiliencesim-cm-metrics { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 18px; }
.resiliencesim-cm-metric { flex: 1 1 110px; background: #eef1f6; border: 1px solid rgba(23,40,60,0.10); border-radius: 10px; padding: 12px 14px; text-align: center; }
.resiliencesim-cm-mv { display: block; font-size: 22px; font-weight: 800; color: #17283c; }
.resiliencesim-cm-ml { display: block; font-size: 12px; font-weight: 600; color: #45607f; margin-top: 2px; }
.resiliencesim-cm-insights-title { font-size: 14px; font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: #45607f; margin-bottom: 8px; }
.resiliencesim-cm-insights { margin: 0; padding-left: 20px; }
.resiliencesim-cm-insights li { font-size: 14px; line-height: 1.5; color: #23324a; margin-bottom: 8px; }

