(function() {
    'use strict';

    class ResilienceAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Building Resilience`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (GBP, £M).
            this.BUDGET_CAP = 6.0;          // hard 2-year cap, £6M
            this.WISHLIST = 14.0;           // £14M wish-list — forces prioritisation
            this.AI_COST = 2.4;             // fashionable AI "resilience platform"
            this.AI_PILOT_COST = 0.4;       // evidence-gathering pilot
            this.TRIGGER_COST = 1.1;        // £1.1M outage cost (context only)
            this.TARGET_RESILIENCE = 65;    // board target (reachable by a sound plan)
            this.STRONG_RESILIENCE = 70;    // genuinely resilient (reachable only by a near-optimal balanced plan)

            // Concept truths.
            this.TRUE_EXISTENTIAL = `wms`;  // the could-kill-us single point of failure
        }

        // Recompute the headline Resilience Score from the driver meters. The defensive
        // (robust) and progressive (adaptive) capabilities combine via a harmonic mean, so
        // over-weighting either one creates a new fragility and is strictly worse than a
        // genuine balance. Existential coverage is weighted heaviest — an unfixed
        // could-kill-us gap caps the score however much adaptive capacity is bought.
        _resilience(ds) {
            const r = Math.max(0, ds.robust);
            const a = Math.max(0, ds.adaptive);
            const balanced = (r + a) > 0 ? (2 * r * a) / (r + a) : 0;
            let score = 0.45 * ds.existential + 0.40 * balanced + 0.15 * ds.culture;
            if (ds.existentialGapOpen) score = Math.min(score, 52); // unpatched could-kill-us hole caps it
            if (ds.overBudget) score -= 10;                          // blew the hard cap
            return Math.max(0, Math.min(100, Math.round(score)));
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                const ds = {
                    existential: 10,        // could-kill-us gaps closed
                    adaptive: 12,           // progressive resilience
                    robust: 18,             // defensive robustness (internal driver)
                    culture: 10,            // cultural / sustainability driver
                    resilience: 0,
                    budgetUsed: 0,          // £M committed
                    aiSpend: 0,
                    overBudget: false,
                    existentialGapOpen: false,
                    targetMissed: false,
                    resilienceHistory: [],
                    existentialHistory: [10],
                    adaptiveHistory: [12],
                    coachMessages: [],
                    lastCoach: ``
                };
                ds.resilience = this._resilience(ds);
                ds.resilienceHistory = [ds.resilience];
                state.domainState = ds;
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    existentialPick: `wms`,
                    triage: `existential`,
                    honesty: 55,
                    appraisal: `ebm`,
                    ai: `reject`,
                    failoverEvidence: `strong`,
                    defensive: 3.0,
                    progressive: 1.8,
                    culture: 1.2,
                    wmsFunded: `yes`,
                    board: `evidence`,
                    sustain: `capability`,
                    measure: `both`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ex = document.getElementById(`existentialInput`);
                const tr = document.getElementById(`triageInput`);
                const hon = document.getElementById(`honestyInput`);
                if (ex) decisions.existentialPick = ex.value;
                if (tr) decisions.triage = tr.value;
                if (hon) decisions.honesty = parseInt(hon.value, 10);
                if (!Number.isFinite(decisions.honesty) || decisions.honesty < 0 || decisions.honesty > 100) {
                    warn(`warn_honesty_range`); return false;
                }
            } else if (round === 2) {
                const ap = document.getElementById(`appraisalInput`);
                const ai = document.getElementById(`aiInput`);
                const fe = document.getElementById(`failoverEvidenceInput`);
                if (ap) decisions.appraisal = ap.value;
                if (ai) decisions.ai = ai.value;
                if (fe) decisions.failoverEvidence = fe.value;
            } else if (round === 3) {
                const def = document.getElementById(`defensiveInput`);
                const pro = document.getElementById(`progressiveInput`);
                const cul = document.getElementById(`cultureInput`);
                const wms = document.getElementById(`wmsFundedInput`);
                if (def) decisions.defensive = parseFloat(def.value);
                if (pro) decisions.progressive = parseFloat(pro.value);
                if (cul) decisions.culture = parseFloat(cul.value);
                if (wms) decisions.wmsFunded = wms.value;
                const parts = [decisions.defensive, decisions.progressive, decisions.culture];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_split_negative`); return false;
                }
                const total = Math.round((decisions.defensive + decisions.progressive + decisions.culture) * 10) / 10;
                if (Math.abs(total - this.BUDGET_CAP) > 0.001) {
                    warn(`warn_split_total`); return false;
                }
            } else if (round === 4) {
                const bo = document.getElementById(`boardInput`);
                const su = document.getElementById(`sustainInput`);
                const me = document.getElementById(`measureInput`);
                const cv = document.getElementById(`convictionInput`);
                if (bo) decisions.board = bo.value;
                if (su) decisions.sustain = su.value;
                if (me) decisions.measure = me.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let existDelta = 0, adaptiveDelta = 0, robustDelta = 0, cultureDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: distinguish the could-kill-us existential threat from the costly-but-survivable.
                if (d.existentialPick === this.TRUE_EXISTENTIAL) {
                    existDelta += 18; robustDelta += 4; coachKey = `coach_r1_wms`;
                } else if (d.existentialPick === `cyber`) {
                    existDelta += 4; coachKey = `coach_r1_cyber`;
                } else if (d.existentialPick === `people`) {
                    existDelta += 2; coachKey = `coach_r1_people`;
                } else {
                    adaptiveDelta -= 2; coachKey = `coach_r1_margin`;
                }

                // Triage: rank by likelihood × impact, isolate the 2-3 existential first.
                switch (d.triage) {
                    case `existential`: existDelta += 14; cultureDelta += 2; if (d.existentialPick === this.TRUE_EXISTENTIAL) coachKey = `coach_r1_sharp`; break;
                    case `allred`: existDelta -= 8; cultureDelta -= 2; coachKey = `coach_r1_allred`; break;
                    case `cheapest`: existDelta -= 6; coachKey = `coach_r1_cheapest`; break;
                    case `recent`: existDelta -= 4; coachKey = `coach_r1_recent`; break;
                }

                // Cultural root cause honesty (efficiency over adaptability).
                if (d.honesty >= 55) { cultureDelta += 10; }
                else if (d.honesty <= 20) { cultureDelta -= 8; coachKey = `coach_r1_lowhonesty`; }
                else { cultureDelta += 4; }

                summaryKey = (d.existentialPick === this.TRUE_EXISTENTIAL && d.triage === `existential`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Rate the evidence — the evidence-based-management discipline.
                switch (d.appraisal) {
                    case `ebm`: adaptiveDelta += 6; cultureDelta += 4; robustDelta += 4; coachKey = `coach_r2_ebm`; break;
                    case `vendor`: robustDelta -= 6; cultureDelta -= 4; coachKey = `coach_r2_vendor`; break;
                    case `consensus`: robustDelta -= 4; coachKey = `coach_r2_consensus`; break;
                    case `benchmark`: robustDelta -= 2; adaptiveDelta -= 2; coachKey = `coach_r2_benchmark`; break;
                }

                // The fashionable AI "resilience platform" on a single case study.
                switch (d.ai) {
                    case `reject`: robustDelta += 6; coachKey = (d.appraisal === `ebm`) ? `coach_r2_aireject` : coachKey; break;
                    case `pilot`: adaptiveDelta += 4; spend += this.AI_PILOT_COST; ds.aiSpend = this.AI_PILOT_COST; coachKey = `coach_r2_aipilot`; break;
                    case `fund`: robustDelta -= 8; adaptiveDelta -= 4; spend += this.AI_COST; ds.aiSpend = this.AI_COST; coachKey = `coach_r2_aifund`; break;
                }

                // Rate the evidence behind the proven WMS failover (single-point-of-failure fix).
                switch (d.failoverEvidence) {
                    case `strong`: existDelta += 12; robustDelta += 6; break;
                    case `moderate`: existDelta += 2; coachKey = `coach_r2_failmoderate`; break;
                    case `weak`: existDelta -= 8; coachKey = `coach_r2_failweak`; break;
                }

                summaryKey = (d.appraisal === `ebm` && d.ai !== `fund` && d.failoverEvidence === `strong`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Prioritise & balance defensive vs progressive within the £6M cap.
                const def = d.defensive, pro = d.progressive, cul = d.culture;
                spend += def + pro + cul;

                // Each pound builds the matching capability. Defensive -> robust, progressive ->
                // adaptive, culture -> culture. The harmonic mean in _resilience() then punishes
                // an all-defence or all-progression portfolio relative to a genuine balance.
                robustDelta += def * 10;
                adaptiveDelta += pro * 11;
                cultureDelta += cul * 12;

                if (def >= 5.0) { coachKey = `coach_r3_alldefence`; }
                else if (pro >= 4.5) { coachKey = `coach_r3_allprogress`; }
                else if (cul < 0.5) { coachKey = `coach_r3_noculture`; }
                else { coachKey = `coach_r3_balanced`; }

                // Is the existential WMS single point of failure actually funded?
                if (d.wmsFunded === `yes`) {
                    existDelta += 20; ds.existentialGapOpen = false;
                } else {
                    existDelta -= 10; ds.existentialGapOpen = true; coachKey = `coach_r3_wmsopen`;
                }

                summaryKey = (d.wmsFunded === `yes` && def < 5.0 && pro < 4.5 && cul >= 0.5) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // Commit & defend the evidence-based plan.
                switch (d.board) {
                    case `evidence`: cultureDelta += 6; adaptiveDelta += 6; coachKey = `coach_r4_evidence`; break;
                    case `more`: cultureDelta -= 6; adaptiveDelta -= 4; coachKey = `coach_r4_more`; break;
                    case `insurance`: robustDelta += 2; adaptiveDelta -= 6; cultureDelta -= 4; coachKey = `coach_r4_insurance`; break;
                }

                // Sustain it as a capability, not a one-off project.
                switch (d.sustain) {
                    case `capability`: cultureDelta += 14; adaptiveDelta += 6; break;
                    case `project`: cultureDelta -= 12; coachKey = `coach_r4_project`; break;
                    case `audit`: cultureDelta += 2; coachKey = `coach_r4_audit`; break;
                }

                // Measure outcomes, not just inputs (leading + lagging indicators).
                switch (d.measure) {
                    case `both`: adaptiveDelta += 8; cultureDelta += 8; coachKey = (d.sustain === `capability` && d.board === `evidence`) ? `coach_r4_strong` : coachKey; break;
                    case `recovery`: adaptiveDelta += 2; coachKey = `coach_r4_recovery`; break;
                    case `spend`: cultureDelta -= 4; coachKey = `coach_r4_spend`; break;
                }

                cultureDelta += Math.round((d.conviction - 60) / 8);

                summaryKey = (d.board === `evidence` && d.sustain === `capability` && d.measure === `both`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting (the same £6M pool funds the AI commitment and the portfolio).
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 10) / 10;
            if (ds.budgetUsed > this.BUDGET_CAP + 0.001) ds.overBudget = true;

            // Apply driver deltas with floors/ceilings (kept low early, headroom into round 4).
            ds.existential = Math.max(0, Math.min(100, ds.existential + existDelta));
            ds.adaptive = Math.max(0, Math.min(100, ds.adaptive + adaptiveDelta));
            ds.robust = Math.max(0, Math.min(100, ds.robust + robustDelta));
            ds.culture = Math.max(0, Math.min(100, ds.culture + cultureDelta));

            const prevResilience = ds.resilience;
            ds.resilience = this._resilience(ds);
            const resilienceDelta = ds.resilience - prevResilience;

            ds.resilienceHistory.push(ds.resilience);
            ds.existentialHistory.push(Math.round(ds.existential));
            ds.adaptiveHistory.push(Math.round(ds.adaptive));

            // v1.1.0: publish composite (0-100) to the reporting/grading layer every period.
            ds.performance = { overallScore: this._composite(ds) };

            if (round === this.ROUNDS.length && ds.resilience < this.TARGET_RESILIENCE) ds.targetMissed = true;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                resilience: ds.resilience,
                resilienceDelta: resilienceDelta,
                existential: Math.round(ds.existential),
                adaptive: Math.round(ds.adaptive),
                robust: Math.round(ds.robust),
                culture: Math.round(ds.culture),
                budgetUsed: ds.budgetUsed,
                overBudget: ds.overBudget,
                existentialGapOpen: ds.existentialGapOpen,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

