            // £6M split live total.
            const splitIds = [`defensiveInput`, `progressiveInput`, `cultureInput`];
            const splitReadout = document.getElementById(`splitReadout`);
            const recompute = function() {
                let total = 0;
                splitIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (splitReadout) splitReadout.textContent = `£` + total.toFixed(1) + `M`;
                const bar = document.querySelector(`.resiliencesim-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.BUDGET_CAP) > 0.001) ? `#c0392b` : ``;
            };
            splitIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

