        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.resilienceHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                resilienceChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.resilienceHistory },
                        { data: ds.existentialHistory },
                        { data: ds.adaptiveHistory }
                    ]
                }
            };
        }

        // Composite (0-100) VERBATIM from v1.0.0 getPerformanceSummary (composite === resilience);
        // written to domainState.performance.overallScore each period for the reporting layer.
        _composite(ds) {
            return Math.round(ds.resilience || 0);
        }

        _cl(key, fallback) {
            try {
                if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                    var v = window.mySimulation.t(key);
                    if (v && v !== key) return v;
                }
            } catch (e) {}
            return fallback;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const resilience = Math.round(ds.resilience);
            const existential = Math.round(ds.existential);
            const adaptive = Math.round(ds.adaptive);
            const robust = Math.round(ds.robust);
            const culture = Math.round(ds.culture);

            const hitTarget = resilience >= this.TARGET_RESILIENCE;
            const balanced = robust >= 45 && adaptive >= 45;
            const existentialCovered = existential >= 70 && !ds.existentialGapOpen;
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            let performanceKey = `grade_luck`;
            if (hitTarget && existentialCovered && balanced && culture >= 55 && resilience >= this.STRONG_RESILIENCE) performanceKey = `grade_resilient`;
            else if (hitTarget && existentialCovered && balanced) performanceKey = `grade_boardready`;
            else if (ds.existentialGapOpen) performanceKey = `grade_gap`;
            else if (ds.overBudget) performanceKey = `grade_overbudget`;
            else if (hitTarget) performanceKey = `grade_unbalanced`;
            else if (resilience > 40) performanceKey = `grade_improving`;
            const performance = T(performanceKey);

            const insights = [];
            if (hitTarget && existentialCovered && balanced) insights.push(window.mySimulation.t(`insight_resilient`));
            else if (ds.existentialGapOpen) insights.push(window.mySimulation.t(`insight_gapopen`));
            else if (ds.overBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            else if (hitTarget) insights.push(window.mySimulation.t(`insight_unbalanced`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (robust >= 55 && adaptive < 35) insights.push(window.mySimulation.t(`insight_alldefence`));
            if (adaptive >= 55 && robust < 35) insights.push(window.mySimulation.t(`insight_allprogress`));
            if (culture < 35) insights.push(window.mySimulation.t(`insight_culture`));
            if (resilience >= this.STRONG_RESILIENCE) insights.push(window.mySimulation.t(`insight_strong`));

            return {
                resilience: resilience,
                existential: existential,
                adaptive: adaptive,
                robust: robust,
                culture: culture,
                hitTarget: hitTarget,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                performanceKey: performanceKey,
                existentialGapOpen: ds.existentialGapOpen,
                overBudget: ds.overBudget,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var ok = !!s.hitTarget;
            var badge = ok
                ? '<span class="resiliencesim-cm-badge resiliencesim-cm-yes">' + T('cm_met') + '</span>'
                : '<span class="resiliencesim-cm-badge resiliencesim-cm-no">' + T('cm_missed') + '</span>';
            var failBadge = (s.existentialGapOpen || s.overBudget)
                ? '<span class="resiliencesim-cm-badge resiliencesim-cm-warn">' + T('cm_failstate_badge') + '</span>'
                : '';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="resiliencesim-cm-metric"><span class="resiliencesim-cm-mv">' + Math.round(s.existential || 0) + '</span><span class="resiliencesim-cm-ml">' + T('cm_m_existential') + '</span></div>'
                + '<div class="resiliencesim-cm-metric"><span class="resiliencesim-cm-mv">' + Math.round(s.adaptive || 0) + '</span><span class="resiliencesim-cm-ml">' + T('cm_m_adaptive') + '</span></div>'
                + '<div class="resiliencesim-cm-metric"><span class="resiliencesim-cm-mv">' + Math.round(s.robust || 0) + '</span><span class="resiliencesim-cm-ml">' + T('cm_m_robust') + '</span></div>'
                + '<div class="resiliencesim-cm-metric"><span class="resiliencesim-cm-mv">' + Math.round(s.culture || 0) + '</span><span class="resiliencesim-cm-ml">' + T('cm_m_culture') + '</span></div>';
            return ''
                + '<div class="resiliencesim-completion">'
                +   '<div class="resiliencesim-cm-head">'
                +     '<div class="resiliencesim-cm-score">' + score + '<span class="resiliencesim-cm-score-max">/100</span></div>'
                +     '<div class="resiliencesim-cm-grade">' + grade + ' ' + badge + failBadge + '</div>'
                +   '</div>'
                +   '<div class="resiliencesim-cm-metrics">' + metrics + '</div>'
                +   '<div class="resiliencesim-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="resiliencesim-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.existentialGapOpen) return window.mySimulation.t(`hint_gap`);
            if (ds.overBudget) return window.mySimulation.t(`hint_budget`);
            if (state.currentPeriod >= 3 && ds.robust >= 50 && ds.adaptive < 30) return window.mySimulation.t(`hint_defence`);
            if (state.currentPeriod >= 3 && ds.adaptive >= 50 && ds.robust < 30) return window.mySimulation.t(`hint_progress`);
            if (ds.culture < 30) return window.mySimulation.t(`hint_culture`);
            if (ds.resilience >= this.TARGET_RESILIENCE && ds.existential >= 70) return window.mySimulation.t(`hint_strong`);
